fn single(x: &[i32], y: &[i32]) -> Vec<i32> {
    // Pre-allocate enough space for all elements
    let mut result = Vec::with_capacity(x.len() + y.len());
    // Extend with all elements from the first slice
    result.extend_from_slice(x);
    // Then extend with all elements from the second slice
    result.extend_from_slice(y);
    result
}

